/* The Try-it questions in pool form; the generator skips them. */
const TRY=['Fictional passage: “Dear Ms. Ortiz: Our class would like to hold the book sale in the gym instead of the hall, because the hall was too small for the crowds last year. May we speak with you on Tuesday?” Who is the intended audience? A: Ms. Ortiz, whom the writer addresses, B: The students writing the letter, C: Anyone who might buy a book. Answer A, B or C.',
 'Fictional passage: “Our town should add a Saturday bus. In a fictional count last spring, 120 riders asked for one.” Which sentence is the evidence? A: Our town should add a Saturday bus, B: In a fictional count last spring, 120 riders asked for one, C: Both sentences are evidence. Answer A, B or C.',
 'Fictional passage: “We shall work, we shall learn, we shall rise.” Which device repeats “we shall” at the start of each clause? A: Simile, B: Hyperbole, C: Anaphora. Answer A, B or C.'];
const tryIt=s=>`Try it: ${s[0].toLowerCase()+s.slice(1)}`;
export default {
id:'language-h-ap-lang-rhetorical-situation',subject:'language',level:5,grade:9,standard:'AP English Language and Composition Course and Exam Description (College Board), Unit 1: Big Ideas RHS, CLE, REO and STL',
title:'Rhetorical Situation',
goal:'Read an argument as a response to a situation: name its exigence, writer, audience, purpose, context and message; see how it appeals to its audience; separate claims, evidence and the reasoning between them; find the thesis; follow how the argument is organized; and explain how word choice and sentence structure shape its effect.',
points:20,
skills:{situation:'The rhetorical situation',audience:'Audience and appeals',claims:'Claims and evidence',thesis:'Thesis',organization:'Reasoning and organization',style:'Style'},
outline:[['RHS-1.A','Identify the components of the rhetorical situation',['situation']],['RHS-1.B','Explain how an argument shows understanding of its audience',['audience']],['CLE-1.A','Identify and explain claims and evidence',['claims']],['CLE-1.B','Identify the thesis and the structure it signals',['thesis']],['REO-1.A','Describe the reasoning, organization and development of an argument',['organization']],['STL-1.A','Explain how word choice, comparisons and syntax contribute to meaning',['style']]],
steps:[
 {skill:'situation',say:'Every text is written in a situation. The writer is the person who creates it, the audience is who it hopes to reach, and the message is what it says. The exigence is the issue or occasion that calls for the text, the purpose is what the writer wants it to do, and the context is the time, place and circumstances. Change any one and the text changes with it.',pic:triangle},
 {skill:'situation',say:'Read an argument backward from its words. Something happened or went wrong, and that is the exigence. The writer decides what to accomplish, and that is the purpose. The purpose shapes the message, such as a request, a warning or a proposal. If you can say what prompted the text and what it wants, you have the situation.',pic:flow('From exigence to message',[['Exigence','What prompts the writing'],['Purpose','What the writer wants'],['Message','What the text says']])},
 {skill:'situation',say:'Context is the setting in time and place, and it changes what words mean. Patrick Henry spoke before the American Revolution, the Declaration came in 1776, Douglass spoke when slavery was still legal, and Lincoln spoke in the Civil War. The same sentence, spoken in another year, would mean something else. Ask when the text was written and what was going on.',pic:{t:'timeline',events:['1775 Henry','1776 Declaration','1852 Douglass','1863 Lincoln','1933 Roosevelt']}},
 {skill:'audience',say:'Writers shape a text for an audience, and the intended audience is the group the writer has in mind, though others may read it too. To see who it is, look at who is addressed, what the text assumes they know and what they care about. A letter to a teacher and a note to a friend can make the same request in very different words.',pic:board('Who is the audience?',['Text: “Dear Mayor Reyes, our street floods.”','Clue: “Dear Mayor Reyes”','Clue: the writer explains the problem','Audience: the mayor, with neighbors reading along'],['official letter','names the reader','needs facts','who reads']),
  check:{prompt:tryIt(TRY[0]),answer:'A',options:['A','B','C'],hint:'Look at who is addressed in the greeting and who is asked to meet on Tuesday.',pic:pass('Fictional passage',['Dear Ms. Ortiz: Our class would like to hold the book sale in the gym instead of the hall, because the hall was too small for the crowds last year.','May we speak with you on Tuesday?'])}},
 {skill:'audience',say:'Writers persuade with three kinds of appeal. Ethos builds trust in the speaker, through credentials, fairness or character. Pathos reaches the audience’s feelings, such as pride, fear or hope. Logos offers reasons and evidence. A strong argument often combines all three and fits them to what the audience believes and values.',pic:flow('Three appeals',[['Ethos','Why trust the speaker'],['Pathos','What the audience feels'],['Logos','What the reasons show']])},
 {skill:'audience',say:'To reach an audience, a writer adapts word choice, tone and evidence. Suppose the same fictional news is told to a bank and to a sibling. The first message is formal and polite, and the second is quick and playful. Neither is wrong; each suits its reader. Look for the signals that show a writer understands what the audience needs and values.',pic:pass('Fictional: one piece of news, two audiences',['To the bank: “I am writing to ask how to open a student account.”','To my sister: “got my first bank card!!”'])},
 {skill:'claims',say:'A claim is the point an argument wants accepted. Evidence is the support: facts, statistics, examples, expert testimony or a short story. Commentary, or reasoning, is the writer’s explanation of how the evidence supports the claim. Without that link, a fact just sits beside the claim.',pic:board('Claim, evidence, commentary',['Claim: The park needs more benches.','Evidence: in a fictional count, 9 of 10 visitors stood.','Commentary: if nearly all visitors had no seat, a bench is needed.','Check: does the evidence fit the claim?'],['the point to prove','a fictional count','the link between them','relevance and sufficiency'])},
 {skill:'claims',say:'Claims come in kinds. A claim of fact can be checked. A claim of value judges worth, such as saying a policy is fair or unfair. A claim of policy says what should be done. Each kind needs different support: facts for a claim of fact, shared standards for a claim of value, and reasons and likely results for a claim of policy.',pic:flow('Three kinds of claim',[['Fact','Can be checked'],['Value','Judges worth'],['Policy','Says what to do']]),
  check:{prompt:tryIt(TRY[1]),answer:'B',options:['A','B','C'],hint:'The first sentence says what the town should do. Which sentence offers a count of riders?',pic:pass('Fictional passage',['Our town should add a Saturday bus.','In a fictional count last spring, 120 riders asked for one.'])}},
 {skill:'thesis',say:'The thesis is the central claim the whole argument defends. It takes a position that a reasonable person could dispute, and it is specific. A topic such as school lunch is not a thesis, and neither is a plain fact. A thesis says what should be believed or done and often gives the reason.',pic:board('Topic or thesis?',['Topic: Sunday library hours','Fact: The library is closed on Sundays.','Thesis: Open Sundays so working families can visit.','Test: could someone disagree?'],['a subject','no position','position, reason','arguable'])},
 {skill:'thesis',say:'A thesis can also act as a map. If it names its reasons, the reader can expect one section for each. A thesis may concede a point with a word like although, then state the position, and in some arguments it is only implied. Reading a thesis closely tells you what the argument promises and how it may be arranged.',pic:flow('A thesis as a roadmap',[['Position','The park needs benches'],['Reasons','Rest, safety, shade'],['Body','One section for each']])},
 {skill:'organization',say:'Arguments are arranged in patterns. Chronological order follows time, cause and effect links events, compare and contrast sets two things side by side, and problem and solution moves from a trouble to a fix. A writer may also build from weaker to stronger points. Name the pattern, and ask why the writer chose it for this audience.',pic:board('Patterns of organization',['Chronological: first, then, finally','Cause and effect: because, so, as a result','Compare and contrast: both, but, whereas','Problem and solution: the trouble, then the fix'],['time order','reasons, results','likeness','trouble, fix'])},
 {skill:'organization',say:'The Gettysburg Address is short, and its movement is easy to follow. It turns from the nation’s founding eighty-seven years earlier, to the war and the battlefield where the audience stood, to the work still left for the living. Moving from past to present to future gives the speech a shape that carries its message of renewed purpose.',pic:flow('How the Address moves',[['Past','The founding, 87 years earlier'],['Present','A war and a battlefield'],['Future','Work for the living']])},
 {skill:'organization',say:'Transitions show how ideas connect. However and but signal contrast, therefore and so signal a result, and for instance introduces an example. A writer may also concede a fair point of an opposing view, then refute it with reasons. Conceding shows fairness, and refuting shows why the position still holds.',pic:board('Signals and moves',['however: a contrast follows','therefore: a result follows','for instance: an example follows','Concede, then refute'],['but, yet','so, thus','such as','grant, then answer'])},
 {skill:'style',say:'Style is how a writer says something, and it serves the situation. Diction is word choice, and syntax is how sentences are built. Parallelism repeats a pattern, anaphora repeats an opening, and antithesis sets opposites in balance. A rhetorical question asks for effect and not for an answer. Always ask what each choice does for the audience and purpose.',pic:board('Devices and their effects',['Parallelism: matching patterns','Anaphora: Every door was shut. Every window was dark.','Antithesis: opposites in balance','Rhetorical question: asked for effect'],['rhythm','force','contrast','thought']),
  check:{prompt:tryIt(TRY[2]),answer:'C',options:['A','B','C'],hint:'The phrase we shall opens each clause. What is the repetition of a beginning called?',pic:pass('Fictional passage',['We shall work, we shall learn, we shall rise.'],false)}},
 {skill:'style',say:'Diction and tone carry attitude. Words with similar meanings can praise or blame, like thrifty and stingy. Formal words can make a writer seem measured and fair. In the Declaration of Independence, the grievances open by stating that the king refused laws needed for the public good. The calm, legal tone presents the colonists as reasonable and not as rebels who acted on a whim.',pic:pass(`${DI}, one grievance`,['He has refused his Assent to Laws, the most wholesome and necessary for the public good.'])},
 {skill:'organization',summary:true,say:'Tie the unit together with one habit. Start with the situation: what prompted the text, who wrote it, whom it addresses, what it wants and when it was written. Then find the claim and the thesis, check the evidence and the reasoning that links it, notice how the argument is arranged, and ask how word choice and sentence shape serve the purpose.',pic:flow('Reading an argument: the habit',[['Situation','Exigence, audience, purpose'],['Argument','Claim, evidence, thesis'],['Craft','Order, diction, syntax']])}],
progression:{requires:['language-m-claims-evidence','language-m-connotation','language-e-compare-viewpoints'],operations:2,demand:'Read nonfiction arguments closely: name the rhetorical situation, show how a text appeals to its audience, separate claims, evidence and reasoning, find the thesis, follow the organization, and explain how word choice and sentence structure serve the writer’s purpose.'},
items(add){
 const seen=new Set(TRY);
 const put=(skill,prompt,answer,pic,explanation,accept)=>{if(seen.has(prompt))return;seen.add(prompt);add(skill,prompt,answer,pic,explanation,accept);};
 ROWS.forEach(([skill,key,q,right,wrong,why],k)=>{const c=choose(right,wrong,k);
  if(!key){put(skill,`${q} ${c.text}. ${ask(c.n)}`,c.letter,null/* 25 Oct: no picture; it only repeated the question in tiny type */,why,[right,dot(right)]);return;}
  const [src,lines,verse]=P(key),text=lines.join(verse?' / ':' ');
  put(skill,`${src}: “${text}” ${q} ${c.text}. ${ask(c.n)}`,c.letter,pass(src,lines),why,[right,dot(right)]);});
}};
